import sys, math
path=sys.argv[1]
K=40
bases='ACGT'
comp={'A':'T','C':'G','G':'C','T':'A'}
L=[[0]*4 for _ in range(K)]
R=[[0]*4 for _ in range(K)]
nL=[0]*K; nR=[0]*K
seq=''; nseq=0

def add(s):
    global nseq
    s=s.upper()
    if len(s)<K: return
    nseq+=1
    for i,ch in enumerate(s[:K]):
        if ch in bases: L[i][bases.index(ch)]+=1; nL[i]+=1
    rr=''.join(comp.get(ch,'N') for ch in reversed(s[-K:]))
    for i,ch in enumerate(rr):
        if ch in bases: R[i][bases.index(ch)]+=1; nR[i]+=1

with open(path) as f:
    for line in f:
        line=line.strip()
        if line.startswith('>'):
            if seq: add(seq)
            seq=''
        else: seq+=line
if seq: add(seq)

def pwm(C,N):
    return [[(x+0.5)/(n+2.0) for x in row] for row,n in zip(C,N)]
PL=pwm(L,nL); PR=pwm(R,nR)
bg=[sum(L[i][b]+R[i][b] for i in range(K)) for b in range(4)]
t=sum(bg); bg=[x/t for x in bg]

def info(row):
    return sum(p*math.log(p/bg[b],2) for b,p in enumerate(row) if p>0)

def axis_scores(P):
    out=[]
    # a2=i+j, so axis coordinate in base-index space is a2/2
    for a2 in range(-2,43):
        dif=[]; wt=[]
        for i in range(K):
            j=a2-i
            if 0<=j<K and i<j and abs(i-a2/2)<=12:
                d=sum((P[i][b]-P[j][3-b])**2 for b in range(4))
                w=0.05+info(P[i])+info(P[j])
                dif.append(d*w); wt.append(w)
        if wt: out.append((sum(dif)/sum(wt),a2/2,len(wt)))
    return sorted(out)

def xcorr():
    out=[]
    # compare PL[i] with PR[i+d]
    for d in range(-15,16):
        vals=[]; ws=[]
        for i in range(K):
            j=i+d
            if 0<=j<K and i<25 and j<25:
                w=0.05+info(PL[i])+info(PR[j])
                vals.append(sum((PL[i][b]-PR[j][b])**2 for b in range(4))*w); ws.append(w)
        out.append((sum(vals)/sum(ws),d,len(ws)))
    return sorted(out)

with open('report.txt','w') as o:
    o.write(f'sequences={nseq} bg='+' '.join(f'{bases[b]}:{bg[b]:.5f}' for b in range(4))+'\\n')
    o.write('left_axis_best (mse axis_index pairs)\\n')
    for x in axis_scores(PL)[:12]: o.write(f'{x[0]:.8f} {x[1]:.1f} {x[2]}\\n')
    o.write('right_axis_best (mse axis_index pairs)\\n')
    for x in axis_scores(PR)[:12]: o.write(f'{x[0]:.8f} {x[1]:.1f} {x[2]}\\n')
    o.write('left_right_xcorr_best (mse d pairs)\\n')
    for x in xcorr()[:12]: o.write(f'{x[0]:.8f} {x[1]} {x[2]}\\n')
    o.write('PWM columns pos L_A L_C L_G L_T L_IC R_A R_C R_G R_T R_IC\\n')
    for i in range(K):
        o.write(str(i)+' '+' '.join(f'{x:.5f}' for x in PL[i])+f' {info(PL[i]):.5f} '+' '.join(f'{x:.5f}' for x in PR[i])+f' {info(PR[i]):.5f}\\n')
