B='ACGT'; comp={'A':'T','C':'G','G':'C','T':'A'}
def mats(k):return [[[0]*4 for _ in range(k)] for g in range(2)]
CR=mats(50); LL=mats(20); RR=mats(20); nr=[0,0]; nf=[0,0]
def fasta(path):
 s='';
 with open(path) as f:
  for line in f:
   line=line.strip()
   if line.startswith('>'):
    if s:yield s
    s=''
   else:s+=line
 if s:yield s
for q,s in enumerate(fasta(sys.argv[1])):
 g=q%2;s=s.upper()
 if len(s)==50:
  s=''.join(comp.get(x,'N') for x in reversed(s));nr[g]+=1
  for i,x in enumerate(s):
   if x in B:CR[g][i][B.index(x)]+=1
for q,s in enumerate(fasta(sys.argv[2])):
 g=q%2;s=s.upper()
 if len(s)>=20:
  nf[g]+=1; l=s[:20];r=''.join(comp.get(x,'N') for x in reversed(s[-20:]))
  for i,x in enumerate(l):
   if x in B:LL[g][i][B.index(x)]+=1
  for i,x in enumerate(r):
   if x in B:RR[g][i][B.index(x)]+=1
def pwm(C):
 return [[(x+.5)/(sum(row)+2) for x in row] for row in C]
def bg(P):
 x=[sum(row[b] for row in P) for b in range(4)];z=sum(x);return [v/z for v in x]
def axis(P):
 b=bg(P); out=[]
 for a in range(20,36):
  dot=xx=yy=0.
  for i in range(50):
   j=2*a-i
   if 0<=j<50 and i<j and abs(i-a)<=12:
    for k in range(4):
     x=P[i][k]-b[k]; y=P[j][3-k]-b[3-k];dot+=x*y;xx+=x*x;yy+=y*y
  out.append((dot/(xx*yy)**.5,a))
 return max(out),sorted(out,reverse=True)[1]
def xcorr(L,R):
 out=[]
 for d in range(-8,9):
  mse=0.;n=0
  for i in range(15):
   j=i+d
   if 0<=j<15:
    mse+=sum((L[i][k]-R[j][k])**2 for k in range(4));n+=1
  out.append((mse/n,d))
 return min(out),sorted(out)[1]
with open('validation.txt','w') as o:
 o.write('group n_centered n_frag axis best_corr runnerup_corr displacement best_mse runnerup_mse shift5 shift3\\n')
 for g in range(2):
  (ac,a),(ac2,a2)=axis(pwm(CR[g]));(xm,d),(xm2,d2)=xcorr(pwm(LL[g]),pwm(RR[g]))
  s3=a-29;s5=29+d-a
  o.write(f'{g} {nr[g]} {nf[g]} {a} {ac:.6f} {ac2:.6f} {d} {xm:.8f} {xm2:.8f} {s5} {s3}\\n')
